import { z } from 'zod/v3';
import path from 'path';
import type { GuidanceDocument } from '../types/guidance';
import type { WorkerSelection } from '../types/change-request-types';
import type { VariantReference } from '../types/variant-reference';
import type { DirectionRef } from '../types/direction-ref';
import type {
  DesignContextEntry,
  HostVariantImplementationWorkItemSnapshot,
  ProjectContext,
  StaticPreviewTargetElement,
  Target,
  VariantWorkItem,
  VariantWorkItemContext,
  WorkItem,
  WorkItemKind,
} from './contracts';
import { AgentVariantsError } from './errors';

export const VARIANT_WORK_ITEM_KINDS = [
  'static_preview',
  'refine_variant',
  'code_gen',
] as const satisfies readonly WorkItemKind[];

export type VariantWorkItemKind = (typeof VARIANT_WORK_ITEM_KINDS)[number];

const variantWorkItemKinds: ReadonlySet<WorkItemKind> = new Set(
  VARIANT_WORK_ITEM_KINDS,
);

export const isVariantWorkItemKind = (
  kind: WorkItemKind,
): kind is VariantWorkItemKind => variantWorkItemKinds.has(kind);

export const isVariantWorkItem = (item: WorkItem): item is VariantWorkItem =>
  isVariantWorkItemKind(item.kind);

const recordOf = <Shape>() =>
  z.custom<Shape>(
    (value) =>
      typeof value === 'object' && value !== null && !Array.isArray(value),
  );

const MAX_SOURCE_REFERENCES = 12;

const variantWorkItemInputFields = z.object({
  workerSelection: recordOf<WorkerSelection>().optional(),
  projectContext: recordOf<ProjectContext>(),
  briefId: z.string().optional(),
  briefLabel: z.string().optional(),
  briefBody: z.string().optional(),
  briefNotes: z.string().optional(),
  directionRef: z
    .custom<DirectionRef>((value) => typeof value === 'string')
    .optional(),
  sourceDirectionRef: z
    .custom<DirectionRef>((value) => typeof value === 'string')
    .optional(),
  visualReferenceUrl: z.string().optional(),
  instruction: z.string().optional(),
  guidance: z.array(recordOf<GuidanceDocument>()).optional(),
  previewRoutes: z.array(z.string()).optional(),
  references: z.array(recordOf<VariantReference>()).optional(),
  runLabel: z.string().optional(),
  requestId: z.string().optional(),
  variantId: z.string().optional(),
  sourceVariantId: z.string().optional(),
  sourceLabel: z.string().optional(),
  sourceBody: z.string().optional(),
  currentHtml: z.string().optional(),
  target: recordOf<Target>().optional(),
  targetElement: recordOf<StaticPreviewTargetElement>().optional(),
  relevantFiles: z.array(z.string()).optional(),
  sourceReferences: z
    .array(
      z
        .string()
        .refine((file) => path.isAbsolute(file) && !file.includes('\0')),
    )
    .max(MAX_SOURCE_REFERENCES)
    .optional(),
  fidelity: z.enum(['low', 'medium', 'high']).optional(),
  designContextEntry: recordOf<DesignContextEntry>().optional(),
  context: recordOf<VariantWorkItemContext>().optional(),
  adoptedFrom: z
    .object({ sessionId: z.string(), variantId: z.string() })
    .optional(),
  qaRetry: z.object({ summary: z.string() }).optional(),
});

const variantWorkItemInputSchemas = {
  static_preview: variantWorkItemInputFields.extend({
    briefId: z.string(),
    briefLabel: z.string(),
  }),
  refine_variant: variantWorkItemInputFields.extend({
    variantId: z.string(),
    instruction: z.string(),
  }),
  code_gen: variantWorkItemInputFields.extend({
    briefId: z.string(),
    briefLabel: z.string(),
    briefBody: z.string(),
  }),
} as const satisfies Record<VariantWorkItemKind, z.ZodTypeAny>;

export type VariantWorkItemInputByKind = {
  [Kind in VariantWorkItemKind]: z.infer<
    (typeof variantWorkItemInputSchemas)[Kind]
  >;
};

export type VariantWorkItemInput =
  VariantWorkItemInputByKind[VariantWorkItemKind];

export const shownDirectionRef = (
  input: Pick<VariantWorkItemInput, 'directionRef' | 'sourceDirectionRef'>,
): { directionRef?: DirectionRef } => {
  const directionRef = input.directionRef ?? input.sourceDirectionRef;
  return directionRef ? { directionRef } : {};
};

export const workItemDirections = (
  input: VariantWorkItemInput,
  mode: HostVariantImplementationWorkItemSnapshot['mode'],
): Pick<
  HostVariantImplementationWorkItemSnapshot,
  'directionRef' | 'direction' | 'sourceDirection'
> => {
  const sourceLabel =
    input.sourceLabel ?? (mode === 'refine' ? input.briefLabel : undefined);
  const sourceBody =
    input.sourceBody ??
    (mode === 'refine' ? input.briefBody : undefined) ??
    sourceLabel;
  return {
    ...shownDirectionRef(input),
    direction: {
      label: input.briefLabel ?? 'Variant',
      brief: input.briefBody ?? input.instruction ?? 'Create this variant',
      ...(input.briefNotes ? { notes: input.briefNotes } : {}),
    },
    ...(sourceLabel && sourceBody
      ? { sourceDirection: { label: sourceLabel, brief: sourceBody } }
      : {}),
  };
};

type VariantWorkItemInputParsers = {
  [Kind in VariantWorkItemKind]: (
    input: unknown,
  ) => z.SafeParseReturnType<unknown, VariantWorkItemInputByKind[Kind]>;
};

const variantWorkItemInputParsers: VariantWorkItemInputParsers = {
  static_preview: (input) =>
    variantWorkItemInputSchemas.static_preview.safeParse(input),
  refine_variant: (input) =>
    variantWorkItemInputSchemas.refine_variant.safeParse(input),
  code_gen: (input) => variantWorkItemInputSchemas.code_gen.safeParse(input),
};

export const parseVariantWorkItemInput = <
  Kind extends VariantWorkItemKind,
>(item: {
  id: string;
  kind: Kind;
  input: unknown;
}): VariantWorkItemInputByKind[Kind] => {
  const result = variantWorkItemInputParsers[item.kind](item.input);
  if (result.success) return result.data;
  const issues = result.error.issues
    .map((issue) => `${issue.path.join('.') || 'input'}: ${issue.message}`)
    .join('; ');
  throw new AgentVariantsError(
    'SCHEMA_VALIDATION_FAILED',
    `Work item ${item.id} has invalid ${item.kind} input (${issues})`,
  );
};
